import java.util.HashMap;
import java.util.Map;
import java.util.Scanner;

public class Main {
    static Map<Integer, Long> cache1 = new HashMap<>();
    static Map<String, Long> cache2 = new HashMap<>();

    public static long getNum1(int n) {
        if (n < 0) {
            return 0;
        }
        if (n < 2) {
            return 1;
        }
        if (!cache1.containsKey(n)) {
            long total = 0;
            for (int i = 0; i < n; i++) {
                total += getNum1(i) * getNum1(n - 1 - i);
            }
            cache1.put(n, total);
        }
        return cache1.get(n);
    }

    public static long getNum2(int n, int h) {
        if (n < 0 || h <= 0 || n >= Math.pow(2, h - 1)) {
            return 0;
        }
        if (n < 2) {
            return 1;
        }
        if (n < h) {
            return getNum1(n);
        }
        String key = n + "," + h;
        if (!cache2.containsKey(key)) {
            long total = 0;
            for (int i = 0; i < n; i++) {
                total += getNum2(i, h - 1) * getNum2(n - 1 - i, h - 1);
            }
            cache2.put(key, total);
        }
        return cache2.get(key);
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int x = scanner.nextInt();
        int y = scanner.nextInt();
        System.out.println(getNum1(x) - getNum2(x, y));
        scanner.close();
    }
}
